-- =============================================================================
-- Archivo:      004_carga_movimientos.sql
-- Propósito:    Cargar el historial real de inventario: lotes, entradas y
--               salidas, con la existencia calculada por los triggers.
-- Proyecto:     Sistema Web de Gestión y Control de Inventario — Laboratorio
--               Privado Quetzaltenango
-- Autor:        Equipo (Cristopher Alexis Castellanos Paz, José Eduardo Escobar)
--               — generado con apoyo de IA (Claude Code); ver
--               docs/bitacora-ia/Bitacora-IA.md para el registro de uso.
-- ARCHIVO GENERADO por sql/dml/generar_carga.py a partir del inventario real
-- del laboratorio (registros en papel, marzo a septiembre de 2026, transcritos
-- a Excel). No editar a mano: corregir el generador y volver a ejecutarlo.
-- Hallazgos y decisiones de la carga: docs/entrega-3/ENTREGA3_REPORTE_CARGA_DATOS.md
-- Descripción:  1188 lotes y 5839 movimientos (1575 entradas, 4264 salidas).
--               Cómo se garantiza la coherencia:
--               1. Todo lote se inserta con cantidad_disponible = 0.
--               2. Los movimientos se insertan EN ORDEN DE FECHA y el
--                  trigger trg_detalle_movimiento_existencia suma o resta
--                  cada detalle. Si una salida excediera la existencia,
--                  el trigger abortaría toda la carga (RN-01/RN-04).
--               3. Las salidas ya vienen repartidas por lote con FEFO
--                  (mismo criterio que sp_registrar_salida).
--               INSERT directo y no CALL: los procedimientos registran
--               con fecha now(); una carga histórica necesita fechas
--               pasadas. Las reglas de existencia viven en el trigger.
--               Responsable: el papel no registra quién hizo cada
--               movimiento; se asignan al usuario encargado.dev (RN-08).
-- Dependencias: 002_carga_catalogo.sql y web/seed_usuarios.py
--               (los movimientos necesitan un usuario responsable)
-- SGBD:         PostgreSQL 14+
-- Ejecutar:     psql -U usuario_app -d inventario_laboratorio -f 004_carga_movimientos.sql
-- =============================================================================

BEGIN;

CREATE TEMP TABLE carga_lote (ref INTEGER, codigo VARCHAR(30), numero_lote VARCHAR(50),
                              proveedor VARCHAR(150), fecha_ingreso DATE, fecha_vencimiento DATE);
CREATE TEMP TABLE carga_movimiento (orden INTEGER, tipo VARCHAR(10), fecha_hora TIMESTAMP, observacion VARCHAR(255));
CREATE TEMP TABLE carga_detalle (orden INTEGER, ref_lote INTEGER, cantidad NUMERIC(10,2), precio NUMERIC(10,2));

